class WorkoutStructureBuilder:

    def __init__(self, workout):

        self.workout = workout

    def build(self):

        estructura = []

        steps = list(
            self.workout.steps.all()
        )

        i = 0

        while i < len(steps):

            step = steps[i]

            # Warmup

            if step.tipo == "warmup":

                estructura.append({

                    "type": "warmup",

                    "duration":
                        step.duracion_segundos
                })

            # Interval + Recovery

            elif (
                step.tipo == "interval"
                and
                step.repeticiones > 1
                and
                i + 1 < len(steps)
                and
                steps[i + 1].tipo == "recovery"
            ):

                recovery = steps[i + 1]

                estructura.append({

                    "type": "repeat",

                    "repeat":
                        step.repeticiones,

                    "steps": [

                        {

                            "type": "run",

                            "distance":
                                step.distancia_metros,

                            "pace":
                                step.ritmo_objetivo,
                        },

                        {

                            "type": "recovery",

                            "duration":
                                recovery.duracion_segundos,
                        }
                    ]
                })

                i += 1

            # INTERVAL SET SIN RECUPERACION EXPLICITA

            elif (
                step.tipo == "interval"
                and
                step.repeticiones > 1
            ):

                estructura.append({

                    "type": "interval_set",

                    "repeat":
                        step.repeticiones,

                    "distance":
                        step.distancia_metros,

                    "pace":
                        step.ritmo_objetivo,

                    "zone":
                        getattr(step, "zona", ""),
                })                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          

